// Only the script-free SVG generated by export_bundle.py is accepted by the caller.
const fs = require('node:fs');
const sharp = require(process.env.ARCHIFY_SHARP_MODULE || 'sharp');
const [source, target] = process.argv.slice(2);
if (!source || !target) throw new Error('source SVG and destination PNG required');
sharp(fs.readFileSync(source), { limitInputPixels: 24000000 })
  .flatten({ background: '#ffffff' }).png().toFile(target)
  .catch(error => { console.error(error.message); process.exitCode = 1; });
